        final RatisExportClient.Job job;try{job=dependencies.delivery().reopen(childPath(slot),context);}catch(Throwable failed){synchronized(this){activeDelivery.remove(slot.childJob());notifyAll();}return CompletableFuture.failedFuture(failed);}
